cases.source:
print("before")
try {
  while true { let i = 0 }
} catch e {
  print("caught")
} finally {
  print("finally")
}
print("after")

while true {
  try {
    print("0123456789")
  } catch e {
    print("caught")
  }
}

def say(x) {
  print("0123456789")
  return x
}
try { map(say, range(100)) } catch e { print("caught") }

try {
  throw("boom")
} finally {
  let i = 0
  while i < 100 { print("0123456789")
 i = i + 1 }
}

